var _markdown = "\n\n# Autocomplete [#autocomplete]\n\n## Basic Autocomplete [#basic-autocomplete]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  suggestions={[\n    'React',\n    'React Native',\n    'TypeScript',\n    'JavaScript',\n    'Node.js',\n  ]}\n  maxSuggestions={5}\n/>\n```\n\n## Advanced Configuration [#advanced-configuration]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  suggestions={suggestions}\n  maxSuggestions={4}\n  highlightMatchedText={true}\n  caseSensitive={false}\n  showAutocompleteBorder={true}\n  autocompleteContainerStyle={styles.autocompleteContainer}\n  autocompleteSuggestionItemStyle={styles.suggestionItem}\n  autocompleteSuggestionTextStyle={styles.suggestionText}\n/>\n```\n\n## Custom Suggestion Rendering [#custom-suggestion-rendering]\n\n```tsx\nconst CustomSuggestion = ({ \n  suggestion, \n  isHighlighted, \n  onPress \n}) => (\n  <TouchableOpacity\n    style={[\n      styles.suggestion,\n      isHighlighted && styles.highlighted\n    ]}\n    onPress={onPress}\n  >\n    <Text style={styles.emoji}>🏷️</Text>\n    <Text style={styles.suggestionText}>{suggestion}</Text>\n  </TouchableOpacity>\n);\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  suggestions={suggestions}\n  renderSuggestion={(suggestion, index, isHighlighted, onPress) => (\n    <CustomSuggestion\n      suggestion={suggestion}\n      isHighlighted={isHighlighted}\n      onPress={onPress}\n    />\n  )}\n/>\n```\n\n## Dynamic Suggestions [#dynamic-suggestions]\n\n```tsx\nconst [suggestions, setSuggestions] = useState([]);\n\nconst fetchSuggestions = async (query) => {\n  try {\n    const response = await fetch(\n      `https://api.example.com/suggestions?q=${query}`\n    );\n    const data = await response.json();\n    setSuggestions(data);\n  } catch (error) {\n    console.error('Error fetching suggestions:', error);\n    setSuggestions([]);\n  }\n};\n\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  suggestions={suggestions}\n  onQueryChange={fetchSuggestions}\n  debounceMs={300}\n/>\n```\n\n## Styling Examples [#styling-examples]\n\n```tsx\nconst styles = StyleSheet.create({\n  autocompleteContainer: {\n    backgroundColor: '#fff',\n    borderRadius: 8,\n    shadowColor: '#000',\n    shadowOffset: { width: 0, height: 2 },\n    shadowOpacity: 0.1,\n    shadowRadius: 4,\n    elevation: 3,\n    maxHeight: 200,\n  },\n  suggestionItem: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    padding: 12,\n    borderBottomWidth: 1,\n    borderBottomColor: '#f0f0f0',\n  },\n  suggestion: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    padding: 12,\n  },\n  highlighted: {\n    backgroundColor: '#f5f5f5',\n  },\n  emoji: {\n    fontSize: 16,\n    marginRight: 8,\n  },\n  suggestionText: {\n    fontSize: 14,\n    color: '#333',\n  },\n});\n```\n";
